constexpr std::uint64_t origin=(1ULL<<54)+333;
template<class F>void until(F predicate,std::source_location location=std::source_location::current()) {
    const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(10);
    while(std::chrono::steady_clock::now()<end){QCoreApplication::processEvents();if(predicate())return;std::this_thread::sleep_for(std::chrono::milliseconds(1));}
    throw std::runtime_error("Recovery workflow timeout at line "+std::to_string(location.line()));
}
void choose(QAction* action,const std::filesystem::path& path) {
    require(action && action->isEnabled(),"Recovery file action unavailable");QTimer timer;bool selected=false,expired=false;int result=-1;QFileDialog* observed=nullptr;QStringList files;
    timer.setInterval(20);const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(5);
    QObject::connect(&timer,&QTimer::timeout,[&]{if(auto* dialog=qobject_cast<QFileDialog*>(QApplication::activeModalWidget())){
        if(dialog!=observed){observed=dialog;QObject::connect(dialog,&QDialog::finished,&timer,[&,dialog](int value){result=value;files=dialog->selectedFiles();});}
        if(std::chrono::steady_clock::now()>end){expired=true;dialog->reject();return;}
        auto* field=dialog->findChild<QLineEdit*>("fileNameEdit");require(field,"Missing file dialog entry");field->setText(QString::fromStdString(path_to_utf8(path)));selected=true;QMetaObject::invokeMethod(dialog,"accept",Qt::QueuedConnection);
    }});
    timer.start();action->trigger();timer.stop();
    // Typing a filename is not proof that exec() accepted it. A rejected or
    // timed-out dialog must fail here instead of masquerading as a lost export.
    if(!selected || expired || result!=QDialog::Accepted || files.isEmpty())throw std::runtime_error("Recovery file dialog did not accept "+path_to_utf8(path)+"; result="+std::to_string(result)+", expired="+std::to_string(expired)+", selected="+files.join("|").toUtf8().toStdString());
}
