// Independent GF(2) division and continuous-time FSK truth, not a call to the
// production recovery provider or its CRC implementation.
std::vector<unsigned> packet(){const std::vector<unsigned> payload{0x41,0x4d,0x43,0};std::uint64_t message=0;for(const auto byte:payload)message=(message<<8)|byte;auto polynomial=(message<<16)^(0xffffULL<<32);for(int bit=47;bit>=16;--bit)if(polynomial&(1ULL<<bit))polynomial^=0x11021ULL<<(bit-16);auto value=payload;value.push_back((polynomial>>8)&255);value.push_back(polynomial&255);return value;}
std::filesystem::path record(const std::filesystem::path& directory,unsigned rate=8000,unsigned count=1541,bool zero=false,bool corrupt=false) {
    auto bytes=packet();if(corrupt)bytes[0]^=1;std::vector<bool> bits;for(const auto byte:bytes)for(unsigned bit=0;bit<8;++bit)bits.push_back((byte>>(7-bit))&1);
    std::vector<double> prefix{0};for(const auto bit:bits)prefix.push_back(prefix.back()+(bit?1000:-1000)*.002);
    Config config;config.rate=rate;config.frequency=433012000;const auto format=SampleFormat::cf32_le;const auto stride=bytes_per_pair(format);Bytes samples(count*stride);
    for(unsigned n=0;n<count;++n){const auto time=double(n)/rate,offset=5./8000;double cycles=-1000*std::min(time,offset);if(time>=offset){const auto position=(time-offset)/.002;const auto slot=static_cast<std::uint64_t>(std::floor(position+1e-10));const auto symbol=slot%bits.size(),period=slot/bits.size();cycles+=period*prefix.back()+prefix[symbol]+(bits[symbol]?1000:-1000)*(time-offset-slot*.002);}const auto sample=std::polar(zero?0.:.6,.37+2*std::numbers::pi*cycles);write_iq_pair(samples.data()+n*stride,format,{float(sample.real()),float(sample.imag())});}
    Recorder recorder(directory,config,"independent-recovery-truth",format);recorder.append(samples);recorder.finish("complete",{{"stream_first_sample",origin}});return directory/"capture.sigmf-meta";
}
