    WaveformRecoveryPanel paired("fr-FR");auto* pairedChoices=paired.controls()->findChild<QComboBox*>("waveform-recovery-provider");const auto pairedChoice=pairedChoices->findData("bounded-lora-paired-crc16");require(pairedChoice>=0 && pairedChoices->itemText(pairedChoice)==QString::fromUtf8("Trame LoRa à codage par paires"),"Resource-only paired provider language did not enter generic selector");pairedChoices->setCurrentIndex(pairedChoice);paired.setInputs(analysis,{});require(paired.controls()->findChild<QLabel*>("waveform-recovery-about")->text().startsWith("Explicit empirical frame-family") && paired.controls()->findChild<QDoubleSpinBox*>("waveform-recovery-param-paired_body_bytes"),"Partial application translation lost per-key fallback or shared parameter rendering");
    auto measurement=provider;measurement.id="independent.measurement";measurement.recover=[](const auto&,const Json&,std::stop_token){RecoveryData data;data.kind=RecoveryKind::measurement;data.stages={{"custom-measurement","stage",{},Json::object(),{{"unknown_measurement",19}},Json::object()}};return data;};register_recovery(measurement);auto measured=std::make_shared<RecoveryResult>(recover_signal(analysis,{origin,16},measurement,Json::object()));applied.provider_id=measurement.id;panel.setResult(measured,applied);auto* pages=panel.findChild<QTabWidget*>("waveform-recovery-pages");require(!pages->isTabVisible(0) && !pages->isTabVisible(1) && !pages->isTabVisible(2) && pages->currentIndex()==3 && panel.findChild<QPlainTextEdit*>("waveform-recovery-details")->toPlainText().contains("unknown_measurement"),"Nondigital evidence was forced into a Hex page or hidden");
