// Explicit review artifacts use the same controls and persistence as the
// contract workflow. They contain synthetic, independently known samples and
// never require a receiver or a user's private recording.
void reviewFixtures(const std::filesystem::path& root) {
    require(root.is_absolute() && std::filesystem::create_directory(root),"Review fixtures require a new absolute directory");
    {
        Config config;config.rate=8000;config.frequency=433012000;const auto format=SampleFormat::cf32_le;const auto stride=bytes_per_pair(format);Bytes samples(4096*stride);
        for(unsigned n=0;n<4096;++n){const auto t=double(n)/config.rate;const auto value=std::polar(.63,.23+2*std::numbers::pi*(-50*t+156.25*t*t))+std::complex<double>{.04,-.03};write_iq_pair(samples.data()+n*stride,format,{float(value.real()),float(value.imag())});}
        const auto directory=root/path_from_utf8("Chirp 已知样本 📡");Recorder recorder(directory,config,"synthetic-review-chirp",format);recorder.append(samples);recorder.finish("complete",{{"stream_first_sample",origin}});
        Fixture ui;QMenu menu;ui.host.addRecordingActions(menu,{directory/"capture.sigmf-meta",ResearchSampleRange{0,4096},{{"review_source","synthetic-known-truth"}}});menu.actions().front()->trigger();ui.ready();
        ui.control<QCheckBox>("waveform-window-enabled")->setChecked(true);auto* fft=ui.control<QComboBox>("waveform-window-fft");fft->setCurrentIndex(fft->findData(256));ui.control<QSpinBox>("waveform-window-hop")->setValue(64);ui.control<QPushButton>("waveform-window-apply")->click();ui.ready();
        ui.control<QCheckBox>("waveform-model-enabled")->setChecked(true);auto* providers=ui.control<QComboBox>("waveform-model-provider");providers->setCurrentIndex(providers->findData("linear-chirp"));
        const auto number=[&](const char* name,double value){ui.control<QDoubleSpinBox>((std::string("waveform-model-param-")+name).c_str())->setValue(value);};number("amplitude",1);number("phase_rad",0);number("carrier_hz",0);number("start_hz",-50);number("end_hz",270);number("duration_seconds",1.024);
        ui.control<QCheckBox>("waveform-model-fit-dc")->setChecked(true);ui.control<QDoubleSpinBox>("waveform-model-time-offset")->setValue(0);ui.control<QSpinBox>("waveform-model-delay-min")->setValue(0);ui.control<QSpinBox>("waveform-model-delay-max")->setValue(0);ui.control<QPushButton>("waveform-model-apply")->click();ui.ready();
        require(ui.state().at("model").at("residual_rms").get<double>()<5e-8,"Review model did not match its independent truth");ui.saveReady();choose(ui.main()->findChild<QAction*>("waveform-save-analysis"),root/path_from_utf8("01-波形与模型.amc-analysis.json"));until([&]{return ui.state().at("last_save").value("committed",false);});
    }
    {
        const auto metadata=record(root/path_from_utf8("FSK 已知样本 📡"));Fixture ui;QMenu menu;ui.host.addRecordingActions(menu,{metadata,ResearchSampleRange{0,1541},{{"review_source","synthetic-known-truth"}}});menu.actions().front()->trigger();ui.ready();ui.control<QCheckBox>("waveform-recovery-enabled")->setChecked(true);ui.number("symbol_offset_samples",5);ui.apply();
        require(ui.state().at("recovery").at("frames")[0].at("state")==1,"Review FSK frame did not validate");ui.saveReady();choose(ui.main()->findChild<QAction*>("waveform-save-analysis"),root/path_from_utf8("02-FSK字节与校验.amc-analysis.json"));until([&]{return ui.state().at("last_save").value("committed",false);});
    }
    loraPhy(root,{});loraPaired(root,{});coherentWorkflow(root,{},false);coherentWorkflow(root,{},true);
    std::filesystem::copy_file(root/path_from_utf8("LoRa 分析 📡.amc-analysis.json"),root/path_from_utf8("03-LoRa-PHY.amc-analysis.json"));
    std::filesystem::copy_file(root/path_from_utf8("成对编码分析 📡.amc-analysis.json"),root/path_from_utf8("04-成对编码候选修复.amc-analysis.json"));
    for(const auto& name:{"01-波形与模型.amc-analysis.json","02-FSK字节与校验.amc-analysis.json","03-LoRa-PHY.amc-analysis.json","04-成对编码候选修复.amc-analysis.json","05-QPSK同步均衡与EVM.amc-analysis.json","06-OFDM同步均衡与EVM.amc-analysis.json"}) {
        Fixture fresh;choose(fresh.main()->findChild<QAction*>("waveform-open-analysis"),root/path_from_utf8(name));fresh.ready();
    }
    write_json(root/"review-manifest.json",{{"scope","synthetic independently known truth; no receiver or private recordings"},{"cases",6},{"portable",true}});
}
